/* @lc app=leetcode id=3947 lang=kotlin */ class Solution { fun maximumSaleItems(items: Array<IntArray>, budget: Int): Int = items.size.let { n -> IntArray(n + 2).also { c -> items.forEach { c[it[0]]++ } }.let { cnt -> IntArray(n + 2).also { s -> (1..n).forEach { d -> (d..n step d).forEach { s[d] += cnt[it] } } }.let { s -> items.map { (f, p) -> p to s[f] - 1 }.sortedBy { it.first }.let { its -> items.minOf { it[1] }.let { q -> its.fold(Triple(budget.toLong(), 0L, true)) { (rem, v, go), (p, fr) -> if (!go || p >= 2L * q) Triple(rem, v, false) else if (fr == 0) Triple(rem, v, go) else minOf(fr.toLong(), rem / p).let { t -> Triple(rem - t * p, v + 2 * t, t == fr.toLong()) } }.let { (rem, v, _) -> (v + rem / q).toInt() } } } } } } }